// Helper function to calculate distinct characters
function CountDistinctCharacters(string: string) : int
    requires string != null
{
    var set: set<char> := {};
    var i: int;
    var n: int := string.Length;
    for i := 0 to n - 1 {
        set := set + {char.ToLower(string[i])}; // Add lower case character to the set
    }
    return set.Size; // Return the size of the set as the count of distinct characters
}

